  const [printBusy,setPrintBusy]=useState(false);
  const [readyPrint,setReadyPrint]=useState(null);
  useEffect(()=>()=>{if(readyPrint)URL.revokeObjectURL(readyPrint);},[readyPrint]);
  useEffect(()=>{printAbort.current?.abort();setReadyPrint(null);},[queue,paperId,orientation,margin,gap,effectiveBleed,pageRange,storeScope,customWidth,customHeight,guides,registration,backX,backY,calibrationX,calibrationY,sheetBack,printOutput,duplexFlip,dpi,guideStyle,guideSides,guideColor,premiumAssets,access.studio]);
  async function exportPrintPDF(direct=false,mode='all'){
    if((mode!=='calibration'&&missingBacks)||printOutside){setStatus('Load your backing access or correct alignment offsets before exporting.');return;}
    if(!perSheet){setStatus('No full-size cards fit. Choose larger paper or reduce the margin.');return;}
    if(printBusy)return;
    setReadyPrint(null);
    setPrintBusy(true);setStatus('Preparing full-color print sheets…');printAbort.current=new AbortController();
    try {
      const [{rasterPrintCard},{createPrintPDF}]=await Promise.all([import('./printRaster.js'),import('./printPDF.js')]);
      printAbort.current?.signal.throwIfAborted();
      const indices=mode==='calibration'?[]:mode==='first'?outputPages.map((p,i)=>p.sheet===outputPages[0]?.sheet?i:-1).filter(i=>i>=0):parsePageRange(pageRange,outputPages.length);
      const job=mode==='calibration'?calibration:await capturePrintJob(document.querySelector('.print-sheets'),outputPages,{
        ...printSettings,pageIndices:indices,signal:printAbort.current.signal,
        onProgress:({done,total,page})=>setStatus(`Preparing page ${page} · card ${done} of ${total} · ${dpi} DPI`)
      },rasterPrintCard);

      printAbort.current?.signal.throwIfAborted();
      const pdf=createPrintPDF(job);
      if(direct){
        setReadyPrint(URL.createObjectURL(pdf.output('blob')));
        setStatus('Print PDF ready at full card size. Open print sheets, then Share → Print. Match the selected paper.');
      }else{
        pdf.save(mode==='calibration'?'the-proxy-plane-calibration.pdf':'the-proxy-plane-sheets.pdf');
        setStatus('Full-color PDF exported. Print at Actual size / 100% with Color selected.');
      }
    }catch(error){setStatus(error.name==='AbortError'?'Print preparation canceled.':'Print preparation failed: '+error.message);}
    finally{setPrintBusy(false);printAbort.current=null;}
  }

