    {menuOpen&&<button className="menu-backdrop" aria-label="Close menu" onClick={()=>setMenuOpen(false)}/>}
    <nav id="main-navigation" aria-label="Main navigation" className={`main-nav ${menuOpen?"menu-open":""}`}>{[['home','♛','Home'],['library','⌕','Card Library'],['deck','⇩','Deck Import'],['studio','✦','Custom Studio'],['kingdom','♜','Gathering Plane'],['vault','◇','My Vault'],['print','▤','Print'],['premium','✧','Premium'],['decks','♧','Premium Decks']].map(([id,icon,label])=><button key={id} className={page===id?'active':''} aria-current={page===id?'page':undefined} onClick={()=>{setPage(id);setMenuOpen(false)}}><span>{icon}</span><span>{label}</span>{id==='print'&&<em>{queue.length}</em>}</button>)}</nav>
